css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; border-radius: 50%; overflow: hidden; background: radial-gradient(circle, #0b0b0b 28%, #1c1c1c); }
.loader span { position: absolute; inset: 0; background: linear-gradient(140deg, var(--accent), var(--accent-2)); clip-path: polygon(50% 50%, 100% 12%, 100% 52%); transform-origin: 50% 50%; animation: iris calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader span:nth-child(1) { transform: rotate(0deg); }
.loader span:nth-child(2) { transform: rotate(60deg); }
.loader span:nth-child(3) { transform: rotate(120deg); }
.loader span:nth-child(4) { transform: rotate(180deg); }
.loader span:nth-child(5) { transform: rotate(240deg); }
.loader span:nth-child(6) { transform: rotate(300deg); }
@keyframes iris { 0%, 100% { rotate: 0deg; } 50% { rotate: -48deg; } }
